$tests = @(
  @('Universe Within: Dreaming Galaxy','Two panels side by side on one image, divided down the middle. LEFT PANEL: the tattoo design alone on a plain white background, shown flat exactly as described, no body, drawn large so it fills most of the panel. RIGHT PANEL: Studio photograph of a real person''s body showing the same exact tattoo where described, healed tattoo on real skin in soft even light, the rest of the body modestly covered by simple plain clothing, only the tattooed area bare, plain seamless light grey studio backdrop - no room, no furniture, no scenery. The tattoo in both panels is identical. The tattoo: Dreaming Galaxy - a woman''s profile with her eyes closed, the back of her head and her flowing hair dissolving into a spiral galaxy of violet, blue and gold nebula with a few small planets drifting out of it, her face staying clean and realistic while the galaxy pours out from her hairline. A Universe Within tattoo in cosmic colour realism. No text, labels, logos or watermarks in the tattoo. In the right panel it is on a woman, outer upper arm, a medium-to-large tattoo that still sits well inside that area, not a full sleeve.'),
  @('Universe Within: The Forest Wolf','Two panels side by side on one image, divided down the middle. LEFT PANEL: the tattoo design alone on a plain white background, shown flat exactly as described, no body, drawn large so it fills most of the panel. RIGHT PANEL: Studio photograph of a real person''s body showing the same exact tattoo where described, healed tattoo on real skin in soft even light, the rest of the body modestly covered by simple plain clothing, only the tattooed area bare, plain seamless light grey studio backdrop - no room, no furniture, no scenery. The tattoo in both panels is identical. The tattoo: The Forest Wolf - the head of a wolf in three-quarter view whose outline holds an entire misty pine forest - tall trees rising from the base of the neck, a mountain ridge across the brow and a crescent moon where the eye would be - the forest and the fur blending at the edges. A Universe Within tattoo in black-and-grey realism with soft mist. No text, labels, logos or watermarks in the tattoo. In the right panel it is on a man, outer forearm, a medium tattoo about the size of his hand, with plenty of bare skin around it.'),
  @('Impossible Fusion: Nature x Machine','Two panels side by side on one image, divided down the middle. LEFT PANEL: the tattoo design alone on a plain white background, shown flat exactly as described, no body, drawn large so it fills most of the panel. RIGHT PANEL: Studio photograph of a real person''s body showing the same exact tattoo where described, healed tattoo on real skin in soft even light, the rest of the body modestly covered by simple plain clothing, only the tattooed area bare, plain seamless light grey studio backdrop - no room, no furniture, no scenery. The tattoo in both panels is identical. The tattoo: Nature x Machine - a lion''s head facing forward, the left half natural with a golden mane and fur, the right half built from brass and steel machinery - gears, pistons, cables and plates - the fur thinning into fine metal filaments along a seam that follows the lion''s own anatomy, both eyes ice-blue. An Impossible Fusion tattoo in colour realism. No text, labels, logos or watermarks in the tattoo. In the right panel it is on a man, outer upper arm, a medium-to-large tattoo that still sits well inside that area, not a full sleeve.'),
  @('Impossible Fusion: Human x Plant','Two panels side by side on one image, divided down the middle. LEFT PANEL: the tattoo design alone on a plain white background, shown flat exactly as described, no body, drawn large so it fills most of the panel. RIGHT PANEL: Studio photograph of a real person''s body showing the same exact tattoo where described, healed tattoo on real skin in soft even light, the rest of the body modestly covered by simple plain clothing, only the tattooed area bare, plain seamless light grey studio backdrop - no room, no furniture, no scenery. The tattoo in both panels is identical. The tattoo: Human x Plant - a woman''s profile with her eyes closed whose hair turns into twisting tree branches and roots, the bark growing into her neck and jaw, small flowers and leaves blooming along the branches. An Impossible Fusion tattoo in soft colour realism in earthy browns and greens with a few pink and violet flowers. No text, labels, logos or watermarks in the tattoo. In the right panel it is on a woman, outer forearm, a medium tattoo about the size of her hand, with plenty of bare skin around it.'),
  @('Hidden Within: Wolf Within','Two panels side by side on one image, divided down the middle. LEFT PANEL: the tattoo design alone on a plain white background, shown flat exactly as described, no body, drawn large so it fills most of the panel. RIGHT PANEL: Studio photograph of a real person''s body showing the same exact tattoo where described, healed tattoo on real skin in soft even light, the rest of the body modestly covered by simple plain clothing, only the tattooed area bare, plain seamless light grey studio backdrop - no room, no furniture, no scenery. The tattoo in both panels is identical. The tattoo: Wolf Within - a realistic wolf''s head as the main image; within the wolf''s facial silhouette a woman''s profile is concealed - her forehead, nose and lips line up with the wolf''s fur and shadows, so the wolf stays the main subject and her face appears in the negative space on a closer look. A Hidden Within tattoo in black-and-grey realism. No text, labels, logos or watermarks in the tattoo. In the right panel it is on a man, outer upper arm, a medium-to-large tattoo that still sits well inside that area, not a full sleeve.'),
  @('Hidden Within: The Butterfly''s Secret','Two panels side by side on one image, divided down the middle. LEFT PANEL: the tattoo design alone on a plain white background, shown flat exactly as described, no body, drawn large so it fills most of the panel. RIGHT PANEL: Studio photograph of a real person''s body showing the same exact tattoo where described, healed tattoo on real skin in soft even light, the rest of the body modestly covered by simple plain clothing, only the tattooed area bare, plain seamless light grey studio backdrop - no room, no furniture, no scenery. The tattoo in both panels is identical. The tattoo: The Butterfly''s Secret - a large butterfly with four detailed wings; each upper wing holds one human face in profile, the two faces looking toward each other across the butterfly''s body, and the lower wings carry soft patterns that echo the faces; the butterfly stays clearly recognisable. A Hidden Within tattoo in colour illustrative realism in deep blue, violet and amber. No text, labels, logos or watermarks in the tattoo. In the right panel it is on a woman, outer calf, a medium tattoo about the size of her hand, with plenty of bare skin around it.')
)
$n = 0; $spent = 0.0
foreach ($t in $tests) { $n++
  $body = @{ subject=$t[1]; model="gpt-image-2"; width=1536; height=1024; exact_size=$true; raw=$true } | ConvertTo-Json -Compress
  try {
    $j = (RUN ("SHOW_IT " + $body)) | ConvertFrom-Json
    if ($j.payload.ok -and $j.payload.id) { $spent += [double]$j.payload.cost_usd; "[" + $n + "/6] " + $t[0] + " - " + $j.payload.image_url + "  $" + $j.payload.cost_usd }
    else { "[" + $n + "/6] " + $t[0] + " - NOT DRAWN: " + $j.payload.error }
  } catch { "[" + $n + "/6] " + $t[0] + " - NOT DRAWN: " + $_.Exception.Message }
}
"== spent: $" + [Math]::Round($spent, 4) + " =="
